<script setup>
import {ref,reactive,nextTick,onMounted,onBeforeUnmount} from 'vue'
import {Globe,House,ChartNoAxesCombined,ShieldCheck,MessagesSquare,ArrowUpRight,ArrowRight,Search,Menu,Compass,Ship,Car,BookOpen,Plus} from 'lucide-vue-next'
import OfficialSources from './OfficialSources.vue'
import * as echarts from 'echarts'
const emit=defineEmits(['open-report'])
const page=ref('首页'),collapsed=ref(false),country=ref('泰国'),industry=ref('新能源汽车'),question=ref(''),reply=ref(''),screened=ref(false),formRef=ref(),chartEl=ref()
const nav=[['首页',House],['市场看板',Globe],['合规筛查',ShieldCheck],['AI 智能问答',MessagesSquare]]
const countries=[{name:'泰国',en:'THAILAND',capital:'曼谷',currency:'泰铢 THB',color:'#dfeee5',desc:'区域汽车产业链与制造业布局',x:46,y:40},{name:'印度尼西亚',en:'INDONESIA',capital:'雅加达',currency:'印尼盾 IDR',color:'#e9e7fa',desc:'群岛经济与跨境消费市场',x:65,y:77},{name:'越南',en:'VIETNAM',capital:'河内',currency:'越南盾 VND',color:'#ffedce',desc:'制造业协作与电商渠道探索',x:61,y:43}]
const policies=['进口关税与税收待遇','产品认证与技术标准','原产地规则与协定适用','市场准入与经营资质','标签、环保与消费者保护']
const form=reactive({country:'泰国',product:'',hs:'',industry:'新能源汽车',origin:'中国'})
const rules={product:[{required:true,message:'请输入产品名称',trigger:'blur'}],hs:[{pattern:/^\d{6}(\d{2})?(\d{2})?$/,message:'请填写 6、8 或 10 位数字',trigger:'blur'}]}
let chart
function draw(){if(!chartEl.value)return;chart=echarts.init(chartEl.value);chart.setOption({tooltip:{trigger:'axis'},grid:{left:40,right:20,top:28,bottom:30},xAxis:{type:'category',data:['Q1','Q2','Q3','Q4'],axisLine:{lineStyle:{color:'#ddd'}}},yAxis:{type:'value',name:'示例指数',splitLine:{lineStyle:{color:'#eee'}}},series:[{type:'bar',data:country.value==='泰国'?[42,58,64,79]:country.value==='越南'?[35,46,60,72]:[50,62,74,88],itemStyle:{color:'#20a7d4',borderRadius:[5,5,0,0]},barWidth:25}]})}
async function go(p){page.value=p;screened.value=false;chart?.dispose();chart=null;await nextTick();if(p==='市场看板')draw();window.scrollTo({top:0})}
async function choose(c){country.value=c;form.country=c;if(page.value!=='市场看板')await go('市场看板');else{chart?.dispose();draw()}}
async function screen(){if(await formRef.value.validate().catch(()=>false))screened.value=true}
function ask(){if(!question.value.trim())return;reply.value=question.value.trim();question.value=''}
function resize(){chart?.resize()}
onMounted(()=>window.addEventListener('resize',resize));onBeforeUnmount(()=>{chart?.dispose();window.removeEventListener('resize',resize)})
</script>
<template>
<div class="shell" :class="{compact:collapsed}">
<aside><div class="brand"><button class="icon" aria-label="折叠导航" @click="collapsed=!collapsed"><Menu :size="22"/></button><span>远航<span class="blue">.</span></span></div><button class="create" @click="go('合规筛查')"><Plus :size="21"/><span>开始出海探索</span></button><nav><button v-for="[label,icon] in nav" :key="label" :class="{active:page===label}" @click="go(label)"><component :is="icon" :size="22"/><span>{{label}}</span></button></nav><div class="aside-bottom"><BookOpen :size="19"/><span>第 1 组 · 初步设计<br><small>演示模式 / 非真实政策数据</small></span></div></aside>
<main><header><div class="breadcrumb">工作空间 <span>/ {{page}}</span></div><span class="prototype">交互原型 v0.1</span><div class="avatar">01</div></header><div class="content"><button class="text-button" style="margin-bottom:16px" @click="emit('open-report',{country:page==='合规筛查'?form.country:country,industry:page==='合规筛查'?form.industry:industry,product:form.product})">查看出海报告样例 ↗</button><div class="notice">混合资料原型 · 下方“官方信息与政策”为已核对来源的资料快照；示例图表、筛查及问答仍为演示。各区块单独标明来源和状态。</div>
<template v-if="page==='首页'"><section class="hero"><div><p class="eyebrow">EXPLORE. UNDERSTAND. GO GLOBAL.</p><h1>让下一站市场，<br>成为有据可循的选择。</h1><p class="intro">从东南亚出发，发现产业机会，厘清贸易规则。<br>让每一次出海决策，都多一份把握。</p><button class="primary" @click="go('市场看板')">探索目标市场 <ArrowRight :size="17"/></button></div><div class="globe-art"><Globe :size="200" :stroke-width=".65"/><span class="orbit-tag">↗ SOUTHEAST ASIA</span><div class="art-caption">连接市场 · 看见可能</div></div></section>
<div class="stats"><div v-for="[value,label] in [['03','重点国家'],['02','聚焦行业'],['05','合规筛查维度'],['RAG','规划中的问答技术']]" :key="label"><strong>{{value}}</strong><span>{{label}}</span></div></div>
<section><div class="section-title"><h2><Compass :size="23"/> 发现重点市场</h2><button class="text-button" @click="go('市场看板')">全部市场 <ArrowRight :size="16"/></button></div><div class="cards"><button class="country-card" v-for="(c,i) in countries" :key="c.name" @click="choose(c.name)"><div class="cover" :style="{background:c.color}"><span class="cover-number">0{{i+1}}</span><Globe :size="92" :stroke-width=".8"/><span>{{c.en}}</span></div><div class="card-body"><small>东南亚 · 目标市场</small><h3>{{c.name}}<ArrowUpRight :size="21"/></h3><p>{{c.desc}}</p><div class="card-footer">查看市场与政策 <ArrowRight :size="17"/></div></div></button></div></section>
<section class="two-col"><div><h2>选择你的行业</h2><button class="industry" v-for="[label,icon] in [['新能源汽车',Car],['跨境电商',Ship]]" @click="industry=label;go('市场看板')"><component :is="icon" :size="28"/><div><h3>{{label}}</h3><p>探索市场机会与合规路径</p></div><ArrowUpRight :size="19"/></button></div><div><h2>重点政策观察</h2><button class="policy-row" v-for="p in policies.slice(0,3)" @click="go('合规筛查')"><span class="policy-dot"></span><div><strong>{{p}}</strong><p>政策条目待接入 · 来源与生效时间待核验</p></div><ArrowUpRight :size="17"/></button></div></section></template>
<template v-if="page==='市场看板'"><p class="eyebrow">MARKET EXPLORER</p><h1>世界很大，从这里出发。</h1><p class="intro">选择东南亚目标市场，了解国家概况与产业观察。</p><div class="toolbar"><el-select v-model="country" @change="choose"><el-option v-for="c in countries" :label="c.name" :value="c.name"/></el-select><el-select v-model="industry"><el-option label="新能源汽车" value="新能源汽车"/><el-option label="跨境电商" value="跨境电商"/></el-select></div><div class="market-layout"><div class="panel map"><div class="section-title"><h2>东南亚市场分布</h2><small>地理位置示意 · 非精确国界</small></div><svg viewBox="0 0 700 380" role="img" aria-label="东南亚位置示意图"><defs><pattern id="grid" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M 35 0 L 0 0 0 35" fill="none" stroke="#dce7e9" stroke-width=".6"/></pattern></defs><rect width="700" height="380" fill="url(#grid)"/><path d="M70 15 L380 15 440 60 401 106 435 151 414 202 380 178 370 218 338 205 330 156 289 147 267 100 204 105 160 66 70 80Z M375 219 L402 244 428 281 413 290 390 266Z M430 299 L487 305 524 323 510 334 460 323Z M503 239 L545 213 572 240 561 283 529 292Z M605 143 L620 176 611 197 597 171Z M580 304 L626 300 655 322 625 333Z" fill="#d5e2df" stroke="white" stroke-width="2"/><text x="60" y="320" fill="#7c9197" font-size="15">INDIAN OCEAN</text></svg><button class="map-pin" v-for="c in countries" :style="{left:c.x+'%',top:(c.y*.76+15)+'%'}" :class="{selected:country===c.name}" @click="choose(c.name)">{{c.name}}</button></div><div class="panel country-detail"><small>COUNTRY OVERVIEW</small><h2>{{country}}</h2><p>{{countries.find(c=>c.name===country).desc}}</p><dl><dt>首都</dt><dd>{{countries.find(c=>c.name===country).capital}}</dd><dt>货币</dt><dd>{{countries.find(c=>c.name===country).currency}}</dd><dt>关注产业</dt><dd>{{industry}}</dd><dt>市场规模 / 供需缺口</dt><dd>待接入经核验数据</dd></dl><button class="primary" @click="form.country=country;form.industry=industry;go('合规筛查')">筛查该市场 <ArrowRight :size="17"/></button></div></div><div class="two-col"><div class="panel"><h2>市场趋势 · 示例指数</h2><div ref="chartEl" class="chart"></div><small>合成数据，仅用于展示图表交互，不表示市场规模。</small></div><div class="panel"><h2>{{country}} · 产业政策</h2><div class="policy-row" v-for="p in policies.slice(0,3)"><ShieldCheck :size="18"/><div><strong>{{p}}</strong><p>官方来源、生效时间、更新时间：待接入</p></div></div></div></div></template>
<template v-if="page==='合规筛查'"><p class="eyebrow">COMPLIANCE CHECK</p><h1>先了解规则，再迈出下一步。</h1><p class="intro">明确产品与目的地，梳理进入目标市场前需要关注的事项。</p><div class="form-layout"><div class="panel"><h2>配置筛查条件</h2><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><div class="form-grid"><el-form-item label="目标国家"><el-select v-model="form.country"><el-option v-for="c in countries" :label="c.name" :value="c.name"/></el-select></el-form-item><el-form-item label="所属行业"><el-select v-model="form.industry"><el-option v-for="i in ['新能源汽车','跨境电商']" :label="i" :value="i"/></el-select></el-form-item><el-form-item label="产品类别 / 产品名称" prop="product"><el-input v-model="form.product" placeholder="例如：纯电动乘用车"/></el-form-item><el-form-item label="HS 编码（选填）" prop="hs"><el-input v-model="form.hs" placeholder="6、8 或 10 位数字" maxlength="10"/></el-form-item><el-form-item label="原产国"><el-select v-model="form.origin"><el-option v-for="c in ['中国','泰国','印度尼西亚','越南','其他']" :label="c" :value="c"/></el-select></el-form-item></div><button class="primary" type="button" @click="screen"><Search :size="17"/> 开始演示筛查</button></el-form></div><div class="guide"><ShieldCheck :size="38"/><h2>合规，从可靠依据开始</h2><p>正式接入后，每一项结果应包含政策原文、适用范围、生效日期与最近更新时间。</p><p>HS 编码仅校验格式，准确归类需由业务人员确认。原型不提供真实税率或法律结论。</p></div></div><section v-if="screened" class="panel result"><h2>{{form.country}} · {{form.product}} 筛查清单</h2><p>演示结果 · 以下是待核验事项，不代表已完成合规审核。</p><el-table :data="policies.map(name=>({name,status:'待核验',source:'尚未接入官方条文',date:'—'}))"><el-table-column prop="name" label="筛查维度"/><el-table-column prop="status" label="状态"/><el-table-column prop="source" label="政策依据"/><el-table-column prop="date" label="生效时间"/></el-table></section></template>
<template v-if="page==='AI 智能问答'"><p class="eyebrow">ASK WITH EVIDENCE</p><h1>关于出海，你想了解什么？</h1><p class="intro">计划通过 RAG 检索政策依据，让回答可以追溯。</p><div class="qa-layout"><div class="panel chat"><div class="assistant-mark"><MessagesSquare :size="28"/></div><h2>你的出海研究助手</h2><p>从市场准入、产品认证或关税规则开始。</p><button class="suggestion" v-for="q in ['纯电动汽车进入泰国，需要关注哪些认证？','跨境电商进入印尼，应该先核验哪些规则？']" @click="question=q">{{q}} <ArrowUpRight :size="16"/></button><div v-if="reply" class="conversation"><div class="user-message">{{reply}}</div><div class="answer"><strong>演示回答 · 未调用 AI</strong><p>建议先核验产品归类、进口主体资质、税收待遇、认证与标签要求。具体要求取决于目标国家、产品和适用日期。</p><p>目前尚未接入政策知识库，无法给出已核实的税率或法规结论。正式回答应附带可打开的原文依据；无充分证据时明确提示无法确认。</p></div></div><form class="composer" @submit.prevent="ask"><label class="sr-only" for="question">输入问题</label><textarea id="question" v-model="question" placeholder="输入你的出海问题…" maxlength="2000"/><button class="primary" :disabled="!question.trim()">发送 <ArrowRight :size="17"/></button></form></div><div class="panel sources"><BookOpen :size="24"/><h2>政策依据</h2><p>提交问题后，此处展示检索到的政策条文。</p><div class="empty">暂无已核验来源</div><dl><dt>数据来源</dt><dd>尚未接入</dd><dt>更新时间</dt><dd>—</dd></dl><small>回答仅供参考，请以官方发布为准。</small></div></div></template>
<OfficialSources v-if="['首页','市场看板','合规筛查'].includes(page)" :country="page==='首页'?'':page==='合规筛查'?form.country:country" :industry="page==='首页'?'':page==='合规筛查'?form.industry:industry"/><footer>远航 · 产业出海智能服务系统 <span>第 1 组 / MVP 交互设计</span></footer></div></main></div>
</template>
